def generate():
    # We need one random test sample: (nums, d)
    # - nums is a list of length n, where 1 <= n <= 1000
    # - Each nums[i] is an int in [1, 1e9]
    # - d is an int in [1, 1e9]
    # Length-related quantities (n) must be sampled uniformly on a log scale.
    import random, math

    def log_uniform_int(lo, hi):
        # Sample integer uniformly in log-space over [lo, hi], with lo >= 1
        if lo < 1:
            lo = 1
        if lo == hi:
            return lo
        x = random.uniform(math.log(lo), math.log(hi))
        v = int(round(math.exp(x)))
        return max(lo, min(hi, v))

    n = log_uniform_int(1, 1000)

    # Choose d. Bias sometimes toward small d to exercise many collisions/mod behavior,
    # but keep within constraints.
    if random.random() < 0.45:
        d = random.randint(1, 1000)
    else:
        d = random.randint(1, 10**9)

    mode = random.random()

    nums = []
    if mode < 0.25:
        # Many duplicates (good for counting logic)
        base = random.randint(1, 10**9)
        nums = [base] * n
    elif mode < 0.50:
        # Values engineered around modulo classes (push sums toward divisibility patterns)
        # Pick a few residues, then create numbers matching those residues mod d.
        # When d is huge, residues are still valid.
        m = random.randint(1, min(10, n))
        residues = [random.randrange(d) if d > 1 else 0 for _ in range(m)]
        for _ in range(n):
            r = random.choice(residues)
            # Create a number in [1, 1e9] with that residue mod d (if possible).
            if d == 1:
                nums.append(random.randint(1, 10**9))
            else:
                # Choose t so that r + t*d is within range, avoid 0
                max_t = (10**9 - r) // d
                if max_t <= 0:
                    # Can't fit; fall back to random
                    nums.append(random.randint(1, 10**9))
                else:
                    t = random.randint(0, max_t)
                    val = r + t * d
                    if val == 0:
                        val += d
                    if val < 1 or val > 10**9:
                        val = random.randint(1, 10**9)
                    nums.append(val)
    elif mode < 0.75:
        # Wide random spread across full range
        nums = [random.randint(1, 10**9) for _ in range(n)]
    else:
        # Mix of small and large values to cover extremes
        for _ in range(n):
            if random.random() < 0.5:
                nums.append(random.randint(1, 1000))
            else:
                nums.append(random.randint(10**9 - 1000, 10**9))

    return nums, d
