def generate():
    # We need to generate a single input sample: a binary string s.
    # Constraints: 3 <= len(s) <= 1e5, characters in {'0','1'}.
    # Length-related quantity (len(s)) should be sampled uniformly on a logarithmic scale.
    # We'll also vary the distribution of ones/zeros to hit important cases:
    # - all zeros (cnt==0 case)
    # - total ones not divisible by 3 (answer 0)
    # - total ones divisible by 3 and >0 (general case)
    import random, math

    def log_uniform_int(lo, hi):
        # Sample integer uniformly in log-space over [lo, hi], lo>=1
        u = random.random()
        x = int(math.exp(math.log(lo) + (math.log(hi) - math.log(lo)) * u))
        return max(lo, min(hi, x))

    n = log_uniform_int(3, 100000)

    mode = random.choices(
        ["all0", "not_div3", "div3_pos", "random"],
        weights=[1, 2, 2, 3],
        k=1
    )[0]

    if mode == "all0":
        return "0" * n

    if mode == "not_div3":
        # Choose ones count k in [1, n] with k % 3 != 0
        if n == 1:
            k = 1
        else:
            k = random.randint(1, n)
        if k % 3 == 0:
            k = 1 if k != 1 else 2
            if k > n:
                k = n - 1  # n>=3 so safe
        arr = ["0"] * n
        for idx in random.sample(range(n), k):
            arr[idx] = "1"
        return "".join(arr)

    if mode == "div3_pos":
        # Choose ones count k in [3, n] with k % 3 == 0
        kmax = n - (n % 3)
        if kmax < 3:
            # fall back to all zeros if can't fit positive multiple of 3 (but n>=3 so kmax>=3)
            return "0" * n
        k = random.randrange(3, kmax + 1, 3)
        arr = ["0"] * n
        for idx in random.sample(range(n), k):
            arr[idx] = "1"
        return "".join(arr)

    # mode == "random": unbiased bits but ensure at least one of each occasionally
    p = random.choice([0.1, 0.3, 0.5, 0.7, 0.9])
    s = "".join("1" if random.random() < p else "0" for _ in range(n))
    return s
