def generate():
    # Think step by step:
    # 1) Sample n uniformly on a logarithmic scale within [1, 2*10^4].
    # 2) Generate nums of length n with each nums[i] in [1, 5*10^4].
    #    Use a few distribution modes (small, large, mixed, repetitive) to cover edge cases.
    # 3) Sample k uniformly on a logarithmic scale within [1, n*(n+1)//2].
    import random, math

    def log_uniform_int(lo, hi):
        lo = max(1, int(lo))
        hi = int(hi)
        if lo > hi:
            lo, hi = hi, lo
        if lo == hi:
            return lo
        a, b = math.log(lo), math.log(hi)
        return int(math.exp(random.uniform(a, b)))

    n = log_uniform_int(1, 2 * 10**4)

    mode = random.random()
    nums = []

    if mode < 0.25:
        # Mostly small numbers
        for _ in range(n):
            nums.append(log_uniform_int(1, 200))
    elif mode < 0.50:
        # Mostly large numbers
        for _ in range(n):
            nums.append(log_uniform_int(10**4, 5 * 10**4))
    elif mode < 0.75:
        # Mixed wide-range numbers
        for _ in range(n):
            nums.append(log_uniform_int(1, 5 * 10**4))
    else:
        # Repetitive / low-entropy array (helps exercise many equal subarray sums)
        v = log_uniform_int(1, 5 * 10**4)
        # Occasionally introduce a second value
        if random.random() < 0.35 and n > 1:
            v2 = log_uniform_int(1, 5 * 10**4)
            for _ in range(n):
                nums.append(v if random.random() < 0.85 else v2)
        else:
            nums = [v] * n

    max_k = n * (n + 1) // 2
    k = log_uniform_int(1, max_k)

    return nums, k
