def generate():
    # We need to generate one random grid per call.
    # Constraints: 1 <= m,n <= 100 and each cell in {1,2,3,4}.
    # Length-related quantities (m and n) must be sampled uniformly on a log scale.
    # We'll sample m and n independently with log-uniform over [1, 100].
    # Then fill an m x n grid with random integers 1..4 (optionally with some structure mix).

    import random
    import math

    def log_uniform_int(lo: int, hi: int) -> int:
        lo = max(lo, 1)  # avoid log(0)
        if lo == hi:
            return lo
        x = random.uniform(math.log(lo), math.log(hi))
        v = int(round(math.exp(x)))
        return max(lo, min(hi, v))

    m = log_uniform_int(1, 100)
    n = log_uniform_int(1, 100)

    mode = random.random()
    grid = [[0] * n for _ in range(m)]

    if mode < 0.50:
        # Pure random
        for i in range(m):
            for j in range(n):
                grid[i][j] = random.randint(1, 4)
    elif mode < 0.75:
        # Mostly points right/down (common "easy" structure), with some noise
        for i in range(m):
            for j in range(n):
                if random.random() < 0.85:
                    grid[i][j] = 1 if random.random() < 0.6 else 3
                else:
                    grid[i][j] = random.randint(1, 4)
    else:
        # Create many left/up pointers (often leads out-of-bounds / requires fixes), with noise
        for i in range(m):
            for j in range(n):
                if random.random() < 0.85:
                    grid[i][j] = 2 if random.random() < 0.5 else 4
                else:
                    grid[i][j] = random.randint(1, 4)

    return grid
