def generate():
    # We need a single sample: (numerator, denominator) as two ints.
    # Constraints: 32-bit signed range; denominator != 0.
    # We'll diversify cases:
    #  - small/simple fractions
    #  - terminating decimals (denominator factors only 2 and/or 5)
    #  - repeating decimals (denominator has other prime factors)
    #  - large magnitude values near 32-bit limits
    #  - random general case
    #
    # For any length-related quantity (here: digit-length / magnitude), sample
    # uniformly on a logarithmic scale: choose number of digits via log-uniform,
    # then choose a random value with that many digits (and random sign).
    import random
    import math

    INT_MIN = -(2**31)
    INT_MAX = 2**31 - 1

    def log_uniform_int(lo, hi):
        # log-uniform over [lo, hi], with lo >= 1
        if lo < 1:
            lo = 1
        x = math.exp(random.uniform(math.log(lo), math.log(hi)))
        v = int(x)
        if v < lo:
            v = lo
        if v > hi:
            v = hi
        return v

    def rand_int_32():
        # Pick magnitude in a log-uniform way, then sign, then clamp.
        # digit length in [1, 10] (since INT_MAX has 10 digits)
        digits = log_uniform_int(1, 10)
        if digits == 10:
            # limit to [1e9, INT_MAX]
            mag = random.randint(10**9, INT_MAX)
        else:
            mag = random.randint(10**(digits - 1), 10**digits - 1)
        if random.random() < 0.5:
            mag = -mag
        # Avoid INT_MIN (abs overflows in some languages; Python is fine, but keep safe-ish)
        if mag == INT_MIN:
            mag = INT_MIN + 1
        return mag

    def make_terminating_den():
        # Denominator = 2^a * 5^b within 32-bit range; choose exponents log-uniform-ish.
        # Exponent ranges capped so value fits INT_MAX.
        # Choose a,b from [0..31] but bias via log-uniform on (a+1),(b+1).
        a = log_uniform_int(1, 32) - 1
        b = log_uniform_int(1, 32) - 1
        val = (2**a) * (5**b)
        # If too big, shrink by reducing exponents
        while val > INT_MAX and (a > 0 or b > 0):
            if a > 0 and (b == 0 or random.random() < 0.6):
                a -= 1
            elif b > 0:
                b -= 1
            val = (2**a) * (5**b)
        if val == 0:
            val = 1
        if random.random() < 0.5:
            val = -val
        return val

    def make_repeating_den():
        # Create denominator that (after simplification) will likely repeat:
        # include a prime factor not in {2,5} (e.g., 3,7,11,13,37,101,9973).
        primes = [3, 7, 11, 13, 27, 37, 101, 1009, 9973, 99991]
        base = random.choice(primes)
        # Multiply by small power of 2 and 5 sometimes (still repeating if base has other factors)
        a = random.randint(0, 10)
        b = random.randint(0, 10)
        val = base * (2**a) * (5**b)
        # Keep within 32-bit
        while val > INT_MAX:
            if a > 0:
                a -= 1
            elif b > 0:
                b -= 1
            else:
                base = random.choice([3, 7, 11, 13, 37, 101])
            val = base * (2**a) * (5**b)
        if random.random() < 0.5:
            val = -val
        if val == 0:
            val = base
        return val

    mode = random.random()

    if mode < 0.10:
        # Simple small numbers (like examples)
        numerator = random.choice([0, 1, 2, 4, -1, -2, -4, 10, -10])
        denominator = random.choice([1, 2, 3, 6, 7, 333, -1, -2, -3, -333])
        if denominator == 0:
            denominator = 1
        return (numerator, denominator)

    if mode < 0.30:
        # Terminating decimals
        denominator = make_terminating_den()
        numerator = rand_int_32()
        if denominator == 0:
            denominator = 1
        return (numerator, denominator)

    if mode < 0.60:
        # Repeating decimals
        denominator = make_repeating_den()
        numerator = rand_int_32()
        if denominator == 0:
            denominator = 1
        return (numerator, denominator)

    if mode < 0.80:
        # Near limits
        numerator = random.choice([INT_MAX, INT_MAX - 1, INT_MIN + 1, -(2**30), 2**30 - 1])
        denominator = random.choice([INT_MAX, INT_MAX - 7, INT_MIN + 1, -1, 1, 2, 3, 7])
        if denominator == 0:
            denominator = 1
        return (numerator, denominator)

    # General random case
    numerator = rand_int_32()
    denominator = rand_int_32()
    if denominator == 0:
        denominator = 1
    return (numerator, denominator)
