def generate():
    # We need to generate one test case: a single list `nums`.
    # Constraints:
    #   2 <= n <= 1e5, 0 <= nums[i] <= 1e9
    # Length-related quantities (here, n) sampled uniformly on a logarithmic scale.
    # We'll also randomize value patterns to stress different behaviors:
    #   - all zeros / sparse positives
    #   - one huge value at the end (max "push-left" effect)
    #   - decreasing/increasing sequences
    #   - random large values, with occasional extremes (0 and 1e9)

    import random
    import math

    def log_uniform_int(lo, hi):
        lo = max(1, lo)  # avoid log(0)
        if lo == hi:
            return lo
        a, b = math.log(lo), math.log(hi)
        return int(math.floor(math.exp(random.uniform(a, b))))

    n = log_uniform_int(2, 10**5)
    n = max(2, min(n, 10**5))

    mode = random.randrange(8)
    nums = [0] * n

    if mode == 0:
        # Fully random
        for i in range(n):
            r = random.random()
            if r < 0.10:
                nums[i] = 0
            elif r < 0.12:
                nums[i] = 10**9
            else:
                nums[i] = random.randint(0, 10**9)

    elif mode == 1:
        # One big value at the end, others small
        for i in range(n - 1):
            nums[i] = random.randint(0, 100)
        nums[-1] = random.randint(0, 10**9)

    elif mode == 2:
        # One big value at the beginning, others random
        nums[0] = random.randint(0, 10**9)
        for i in range(1, n):
            nums[i] = random.randint(0, 10**9)

    elif mode == 3:
        # Sparse positives: choose k positions, put large values there
        k = log_uniform_int(1, n)
        k = max(1, min(k, n))
        idxs = random.sample(range(n), k)
        for i in idxs:
            nums[i] = random.randint(1, 10**9)

    elif mode == 4:
        # Nondecreasing sequence with noise
        cur = random.randint(0, 10**6)
        for i in range(n):
            cur = min(10**9, cur + random.randint(0, 10**6))
            nums[i] = cur if random.random() > 0.05 else random.randint(0, 10**9)

    elif mode == 5:
        # Nonincreasing sequence with noise
        cur = random.randint(0, 10**9)
        for i in range(n):
            cur = max(0, cur - random.randint(0, 10**6))
            nums[i] = cur if random.random() > 0.05 else random.randint(0, 10**9)

    elif mode == 6:
        # Alternating extremes
        for i in range(n):
            if i % 2 == 0:
                nums[i] = random.randint(0, 10)
            else:
                nums[i] = random.randint(10**9 - 10**6, 10**9)

    else:
        # Small n edge case bias + random values
        if random.random() < 0.5:
            n2 = log_uniform_int(2, 50)
            n2 = max(2, min(n2, 50))
            n = n2
        nums = [random.randint(0, 10**9) for _ in range(n)]
        if random.random() < 0.3:
            nums[random.randrange(n)] = 0
        if random.random() < 0.3:
            nums[random.randrange(n)] = 10**9

    return nums
