def generate():
    # We need to generate one random string s of 'a'/'b' with:
    # 1 <= len(s) <= 1e5, and lengths sampled uniformly on a log scale.
    # We'll also vary structure to hit edge cases (all one char, mostly one char,
    # alternating, random, and blocky runs), while still respecting constraints.
    import random, math

    def log_uniform_int(lo, hi):
        lo = max(1, lo)  # avoid log(0)
        if lo == hi:
            return lo
        x = random.uniform(math.log(lo), math.log(hi))
        v = int(round(math.exp(x)))
        return max(lo, min(hi, v))

    n = log_uniform_int(1, 100000)

    mode = random.random()
    if mode < 0.10:
        # all 'a'
        return "a" * n
    elif mode < 0.20:
        # all 'b'
        return "b" * n
    elif mode < 0.35:
        # mostly one char with a few flips
        dominant = random.choice(["a", "b"])
        other = "b" if dominant == "a" else "a"
        p_other = random.uniform(0.001, 0.05)
        return "".join(other if random.random() < p_other else dominant for _ in range(n))
    elif mode < 0.50:
        # alternating pattern with a random start
        start = random.choice(["a", "b"])
        other = "b" if start == "a" else "a"
        return "".join(start if i % 2 == 0 else other for i in range(n))
    elif mode < 0.75:
        # blocky runs: choose number of runs on a log scale, then random run lengths
        k = log_uniform_int(1, min(n, 5000))
        chars = []
        cur = random.choice(["a", "b"])
        remaining = n
        for i in range(k):
            if i == k - 1:
                run = remaining
            else:
                # ensure at least 1 per remaining run
                max_run = remaining - (k - i - 1)
                run = log_uniform_int(1, max_run)
            chars.append(cur * run)
            remaining -= run
            cur = "b" if cur == "a" else "a"
            if remaining <= 0:
                break
        s = "".join(chars)
        if len(s) < n:
            s += (random.choice(["a", "b"]) * (n - len(s)))
        return s[:n]
    else:
        # fully random with p(a) chosen randomly
        p_a = random.random()
        return "".join("a" if random.random() < p_a else "b" for _ in range(n))
