def generate():
    # We need to generate one random input sample: a single string s.
    # Constraints: 1 <= n = len(s) <= 200, and s consists only of 'I'/'D'.
    # Length-related quantity n should be sampled uniformly on a logarithmic scale in [1, 200].
    # Then generate each character independently as 'I' or 'D' (with slight bias sometimes to hit extremes).

    import random, math

    def log_uniform_int(lo, hi):
        lo = max(1, lo)  # avoid log(0)
        if lo == hi:
            return lo
        x = random.uniform(math.log(lo), math.log(hi))
        v = int(round(math.exp(x)))
        return max(lo, min(hi, v))

    n = log_uniform_int(1, 200)

    # Occasionally force structured patterns to stress DP edge behavior.
    mode = random.random()
    if mode < 0.10:
        s = "I" * n
    elif mode < 0.20:
        s = "D" * n
    elif mode < 0.30:
        s = ("ID" * (n // 2)) + ("I" if n % 2 else "")
    elif mode < 0.40:
        s = ("DI" * (n // 2)) + ("D" if n % 2 else "")
    else:
        s = "".join(random.choice("ID") for _ in range(n))

    return s
