def generate():
    # We need to generate one random test case: a single list `prices`.
    # Constraints:
    #   1 <= n <= 1000
    #   1 <= prices[i] <= 1e5
    # Length-related quantity n must be sampled uniformly on a logarithmic scale.
    # We'll do: n = round(exp(uniform(log(1), log(1000)))) and clamp to [1,1000].
    # Then generate prices with some variety (uniform, small, large, mixed), all within bounds.

    import random
    import math

    def log_uniform_int(lo, hi):
        lo = max(1, lo)  # avoid log(0)
        x = math.exp(random.uniform(math.log(lo), math.log(hi)))
        v = int(round(x))
        return max(lo, min(hi, v))

    n = log_uniform_int(1, 1000)

    mode = random.random()
    prices = []

    if mode < 0.20:
        # Mostly small values
        for _ in range(n):
            prices.append(random.randint(1, 20))
    elif mode < 0.40:
        # Mostly large values
        for _ in range(n):
            prices.append(random.randint(80000, 100000))
    elif mode < 0.60:
        # Mixed: many small, some spikes
        for _ in range(n):
            if random.random() < 0.85:
                prices.append(random.randint(1, 50))
            else:
                prices.append(random.randint(1, 100000))
    elif mode < 0.80:
        # Log-uniform prices across full range
        for _ in range(n):
            prices.append(log_uniform_int(1, 100000))
    else:
        # Structured: increasing-ish with noise, clamped
        base = random.randint(1, 100)
        for i in range(n):
            val = base + int((i / max(1, n - 1)) * random.randint(0, 100000))
            val += random.randint(-1000, 1000)
            prices.append(max(1, min(100000, val)))

    return prices
