def generate():
    # We need to generate a single random isWater matrix (m x n).
    # Constraints:
    # - 1 <= m, n <= 1000
    # - entries are 0/1
    # - at least one water cell (1)
    # Length-like quantities (m, n, counts) should be sampled uniformly on a log scale.
    #
    # We'll:
    # 1) Sample m and n log-uniformly from [1, 1000].
    # 2) Choose a pattern mode to cover edge cases:
    #    - single water cell
    #    - all water
    #    - random Bernoulli with log-uniform density
    #    - stripes / checker / clusters to stress BFS frontiers
    # 3) Ensure at least one water cell.

    import random, math

    def log_uniform_int(lo, hi):
        lo = max(1, lo)
        a, b = math.log(lo), math.log(hi)
        return int(math.floor(math.exp(random.uniform(a, b))))

    m = log_uniform_int(1, 1000)
    n = log_uniform_int(1, 1000)

    mode = random.choices(
        ["single", "all", "bernoulli", "stripes", "checker", "clusters"],
        weights=[18, 6, 40, 12, 10, 14],
        k=1,
    )[0]

    isWater = [[0] * n for _ in range(m)]

    if mode == "single":
        # Exactly one water cell (maximizes distances).
        i = random.randrange(m)
        j = random.randrange(n)
        isWater[i][j] = 1

    elif mode == "all":
        # All water cells.
        for i in range(m):
            row = isWater[i]
            for j in range(n):
                row[j] = 1

    elif mode == "bernoulli":
        # Choose density p log-uniform in [1/(m*n), 1] to vary sparsity widely.
        mn = m * n
        # log-uniform in [1/mn, 1]
        p = math.exp(random.uniform(math.log(1.0 / mn), 0.0))
        # Slight bias to avoid ultra-dense too often
        if random.random() < 0.5:
            p *= 0.5
        water_count = 0
        for i in range(m):
            row = isWater[i]
            for j in range(n):
                if random.random() < p:
                    row[j] = 1
                    water_count += 1
        if water_count == 0:
            isWater[random.randrange(m)][random.randrange(n)] = 1

    elif mode == "stripes":
        # Vertical or horizontal stripes with log-uniform stripe width.
        stripe_w = log_uniform_int(1, max(1, min(m, n)))
        vertical = random.random() < 0.5
        if vertical:
            for j in range(n):
                if (j // stripe_w) % 2 == 1:
                    for i in range(m):
                        isWater[i][j] = 1
        else:
            for i in range(m):
                if (i // stripe_w) % 2 == 1:
                    for j in range(n):
                        isWater[i][j] = 1
        # Ensure at least one water
        if all(v == 0 for row in isWater for v in row):
            isWater[random.randrange(m)][random.randrange(n)] = 1

    elif mode == "checker":
        # Checkerboard, possibly with a block size > 1 (log-uniform).
        block = log_uniform_int(1, max(1, min(m, n)))
        for i in range(m):
            for j in range(n):
                if ((i // block) + (j // block)) % 2 == 0:
                    isWater[i][j] = 1
        # Ensure at least one water
        if all(v == 0 for row in isWater for v in row):
            isWater[0][0] = 1

    else:  # "clusters"
        # Place several seed water cells and grow clusters via random walks.
        mn = m * n
        seeds = log_uniform_int(1, min(200, mn))
        steps_per_seed = log_uniform_int(1, max(1, (m + n)))
        for _ in range(seeds):
            x = random.randrange(m)
            y = random.randrange(n)
            isWater[x][y] = 1
            for _ in range(steps_per_seed):
                r = random.random()
                if r < 0.25 and x > 0:
                    x -= 1
                elif r < 0.50 and x + 1 < m:
                    x += 1
                elif r < 0.75 and y > 0:
                    y -= 1
                elif y + 1 < n:
                    y += 1
                isWater[x][y] = 1
        # Ensure at least one water
        if all(v == 0 for row in isWater for v in row):
            isWater[random.randrange(m)][random.randrange(n)] = 1

    return isWater
