def generate():
    # We need to generate one random grid sample per call.
    # Input format must be: grid = List[List[int]] with n x n.
    # Constraints: 1 <= n <= 50, values in {-1,0,1}, start/end not -1.
    # Length sampling must be uniform on a logarithmic scale: sample n in [1,50] log-uniform.
    # We'll also randomize obstacle/cherry density (not required, but helps diversity), while
    # ensuring start/end are passable. Sometimes we force a guaranteed path to avoid all-dead cases.

    import random
    import math

    def log_uniform_int(lo, hi):
        lo = max(lo, 1)  # avoid log(0)
        a, b = math.log(lo), math.log(hi)
        x = math.exp(random.uniform(a, b))
        k = int(round(x))
        return max(lo, min(hi, k))

    n = log_uniform_int(1, 50)

    # Choose densities (somewhat varied). p_thorn controls -1; p_cherry controls 1 among non-thorns.
    # Use a mixture to cover sparse/dense thorns cases.
    mode = random.random()
    if mode < 0.25:
        p_thorn = random.uniform(0.00, 0.10)
    elif mode < 0.75:
        p_thorn = random.uniform(0.10, 0.35)
    else:
        p_thorn = random.uniform(0.35, 0.60)
    p_cherry = random.uniform(0.15, 0.70)

    grid = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            r = random.random()
            if r < p_thorn:
                grid[i][j] = -1
            else:
                grid[i][j] = 1 if random.random() < p_cherry else 0

    # Enforce constraints on endpoints.
    grid[0][0] = 1 if random.random() < 0.5 else 0
    grid[n - 1][n - 1] = 1 if random.random() < 0.5 else 0

    # With some probability, force at least one valid path from (0,0) to (n-1,n-1)
    # by carving a random monotone path and ensuring it's not blocked.
    if n > 1 and random.random() < 0.6:
