        path = [(0, 0)]
        while i != n - 1 or j != n - 1:
            if i == n - 1:
                j += 1
            elif j == n - 1:
                i += 1
            else:
                if random.random() < 0.5:
                    i += 1
                else:
                    j += 1
            path.append((i, j))
        for (x, y) in path:
            if grid[x][y] == -1:
                grid[x][y] = 0
            # Sprinkle cherries on the carved path sometimes.
            if random.random() < 0.4:
                grid[x][y] = 1

        # Re-assert endpoints (in case modified).
        grid[0][0] = 1 if random.random() < 0.5 else 0
        grid[n - 1][n - 1] = 1 if random.random() < 0.5 else 0

    return grid
