def generate():
    # Step 1: Choose grid dimensions m,n uniformly on a log scale in [3, 500].
    # Step 2: Choose threshold in [0,255], with some bias toward edge cases (0, 1, 255).
    # Step 3: Generate an image with values in [0,255].
    #         Mix several patterns to exercise region-detection logic:
    #           - fully random
    #           - smooth (likely many valid 3x3 regions for moderate thresholds)
    #           - blocky/constant tiles (many regions if threshold >= 0)
    #           - high-contrast checker/stripes (few regions unless threshold large)
    import random, math

    def log_uniform_int(lo, hi):
        lo = max(lo, 1)
        a = math.log(lo)
        b = math.log(hi)
        return int(math.exp(random.uniform(a, b)))

    m = log_uniform_int(3, 500)  # rows
    n = log_uniform_int(3, 500)  # cols

    thr_choices = [0, 1, 2, 3, 5, 10, 12, 20, 50, 128, 200, 254, 255]
    if random.random() < 0.6:
        threshold = random.choice(thr_choices)
    else:
        threshold = random.randint(0, 255)

    mode = random.choices(
        ["random", "smooth", "blocky", "checker", "stripes"],
        weights=[35, 25, 15, 15, 10],
        k=1
    )[0]

    image = [[0] * n for _ in range(m)]

    if mode == "random":
        for i in range(m):
            row = image[i]
            for j in range(n):
                row[j] = random.randint(0, 255)

    elif mode == "smooth":
        # Random walk style with small step; clamp to [0,255]
        base = random.randint(0, 255)
        max_step = random.choice([1, 2, 3, 5, 8, 13, 20, 40])
        for i in range(m):
            if i == 0:
                prev_row = [base] * n
            else:
                prev_row = image[i - 1]
            cur = image[i]
            cur[0] = max(0, min(255, prev_row[0] + random.randint(-max_step, max_step)))
            for j in range(1, n):
                # Blend influence from left and above to keep it smooth
                target = (cur[j - 1] + prev_row[j]) // 2
                cur[j] = max(0, min(255, target + random.randint(-max_step, max_step)))

    elif mode == "blocky":
        # Piecewise-constant tiles
        tile_h = max(1, log_uniform_int(1, min(100, m)))
        tile_w = max(1, log_uniform_int(1, min(100, n)))
        for ti in range(0, m, tile_h):
            for tj in range(0, n, tile_w):
                val = random.randint(0, 255)
                for i in range(ti, min(m, ti + tile_h)):
                    row = image[i]
                    for j in range(tj, min(n, tj + tile_w)):
                        row[j] = val

    elif mode == "checker":
        a = random.randint(0, 255)
        b = random.randint(0, 255)
        while b == a:
            b = random.randint(0, 255)
        for i in range(m):
            row = image[i]
            for j in range(n):
                row[j] = a if ((i + j) & 1) == 0 else b

    else:  # "stripes"
        vertical = random.random() < 0.5
        period = max(1, log_uniform_int(1, min(50, n if vertical else m)))
        vals = [random.randint(0, 255) for _ in range(period)]
        for i in range(m):
            row = image[i]
            for j in range(n):
                idx = (j if vertical else i) % period
                row[j] = vals[idx]

    return image, threshold
