def generate():
    # We need to generate one random test case matching:
    # (price: List[int], tastiness: List[int], maxAmount: int, maxCoupons: int)
    # Constraints:
    # 1 <= n <= 100
    # 0 <= price[i], tastiness[i], maxAmount <= 1000
    # 0 <= maxCoupons <= 5
    # Length-related quantities must be sampled uniformly on a logarithmic scale (n here).
    #
    # We'll:
    # - Sample n log-uniformly in [1, 100].
    # - Generate price/tastiness with values in [0, 1000], with a mix of edge values and random.
    # - Sample maxAmount in [0, 1000] (include edges often).
    # - Sample maxCoupons in [0, 5] (include edges often).
    import random, math

    def log_uniform_int(lo, hi):
        # Uniform in log space over integers [lo, hi], lo>=1
        if lo == hi:
            return lo
        x = random.uniform(math.log(lo), math.log(hi))
        v = int(math.floor(math.exp(x)))
        if v < lo:
            v = lo
        if v > hi:
            v = hi
        return v

    n = log_uniform_int(1, 100)

    def rand_0_1000():
        # Bias toward edges and small numbers to stress DP transitions.
        r = random.random()
        if r < 0.10:
            return 0
        if r < 0.20:
            return 1000
        if r < 0.35:
            return random.randint(0, 20)
        return random.randint(0, 1000)

    price = [rand_0_1000() for _ in range(n)]
    tastiness = [rand_0_1000() for _ in range(n)]

    # maxAmount not length-related; still include edge-heavy distribution.
    r = random.random()
    if r < 0.15:
        maxAmount = 0
    elif r < 0.30:
        maxAmount = 1000
    elif r < 0.45:
        maxAmount = random.randint(0, 50)
    else:
        maxAmount = random.randint(0, 1000)

    # maxCoupons in [0,5], include edges.
    r = random.random()
    if r < 0.25:
        maxCoupons = 0
    elif r < 0.45:
        maxCoupons = 5
    else:
        maxCoupons = random.randint(0, 5)

    return price, tastiness, maxAmount, maxCoupons
